from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    result = []

    weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}

    def add_months(year, month, offset):
        total = year * 12 + (month - 1) + offset
        return total // 12, total % 12 + 1

    if parts[0] == "DAILY":
        interval = int(parts[1])
        current = start_date
        for _ in range(count):
            result.append(current.isoformat())
            current += timedelta(days=interval)

    elif parts[0] == "WEEKLY":
        interval = int(parts[1])
        selected = sorted(weekdays[x] for x in parts[2].split(","))
        week_start = start_date - timedelta(days=start_date.weekday())

        week_index = 0
        while len(result) < count:
            base = week_start + timedelta(days=week_index * 7)
            for wd in selected:
                candidate = base + timedelta(days=wd)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        break
            week_index += interval

    elif parts[0] == "MONTHLY":
        interval = int(parts[1])

        if len(parts) == 3:
            day_spec = int(parts[2])
            month_offset = 0
            while len(result) < count:
                year, month = add_months(start_date.year, start_date.month, month_offset)
                last_day = calendar.monthrange(year, month)[1]
                day = last_day if day_spec == -1 else day_spec

                if day <= last_day:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())

                month_offset += interval

        else:
            n = int(parts[2])
            target_wd = weekdays[parts[3]]
            month_offset = 0

            while len(result) < count:
                year, month = add_months(start_date.year, start_date.month, month_offset)
                last_day = calendar.monthrange(year, month)[1]

                if n == -1:
                    candidate = date(year, month, last_day)
                    candidate -= timedelta(days=(candidate.weekday() - target_wd) % 7)
                else:
                    first = date(year, month, 1)
                    day = 1 + (target_wd - first.weekday()) % 7 + (n - 1) * 7
                    candidate = date(year, month, day) if day <= last_day else None

                if candidate is not None and candidate >= start_date:
                    result.append(candidate.isoformat())

                month_offset += interval

    else:  # YEARLY
        interval = int(parts[1])
        month, day = map(int, parts[2].split("-"))
        year = start_date.year

        while len(result) < count:
            try:
                candidate = date(year, month, day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
            except ValueError:
                pass
            year += interval

    return result
